SELECT id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE account_id = #{accountId}

SELECT id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE account_id = #{accountId}
AND status IN ('BOOKED', 'CANCELED')
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE event_schedule_id = #{eventScheduleId}
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_booking
WHERE account_id = #{accountId}

SELECT COUNT(*)
FROM tb_booking
WHERE event_schedule_id = #{eventScheduleId}

SELECT id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE id = #{id}

SELECT event_schedule_id AS eventScheduleId, COUNT(*) AS ticketCount FROM tb_booking WHERE status = 'BOOKED' AND event_schedule_id IN
#{id}
GROUP BY event_schedule_id

SELECT id, event_schedule_id, tenant_id
FROM tb_booking
WHERE account_id = #{accountId} AND status = 'BOOKED'

    AND id < #{cursor}

ORDER BY id DESC
LIMIT #{size}

